using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PetFlowAPI.Domain.Entities;

namespace PetFlowAPI.Infrastructure.Persistence.Configurations;

internal static class ConfigurationExtensions
{
    /// <summary>Chave primária identity (GENERATED BY DEFAULT AS IDENTITY no Oracle).</summary>
    public static void IdentityKey<T>(this EntityTypeBuilder<T> builder) where T : class
        => builder.HasKey("Id");

    /// <summary>Coluna VARCHAR2(n), como no DDL.</summary>
    public static PropertyBuilder<string?> Varchar<T>(this EntityTypeBuilder<T> builder, string property, int length, bool required)
        where T : class
    {
        var p = builder.Property<string?>(property).HasMaxLength(length).IsUnicode(false);
        return required ? p.IsRequired() : p;
    }

    public static PropertyBuilder<DateTime> CreatedAt<T>(this EntityTypeBuilder<T> builder, string property = "CreatedAt")
        where T : class
        => builder.Property<DateTime>(property).HasColumnType("TIMESTAMP").HasDefaultValueSql("CURRENT_TIMESTAMP");
}

internal sealed class TutorConfiguration : IEntityTypeConfiguration<Tutor>
{
    public void Configure(EntityTypeBuilder<Tutor> b)
    {
        b.ToTable("TUTOR");
        b.IdentityKey();
        b.Varchar(nameof(Tutor.Role), 20, true).HasDefaultValue("TUTOR");
        b.Varchar(nameof(Tutor.Name), 100, true);
        b.Varchar(nameof(Tutor.Email), 100, true);
        b.Varchar(nameof(Tutor.Phone), 20, false);
        b.Varchar(nameof(Tutor.PasswordHash), 255, true);
        b.CreatedAt();
        b.HasIndex(t => t.Email).IsUnique();
        b.Ignore(t => t.IsAdmin);
    }
}

